def solve(n, edges):
    """Return the lexicographically smallest topological ordering of a DAG.
    Nodes are 0..n-1. ``edges`` is an iterable of [a, b] meaning a -> b.
    If a cycle exists, return an empty list.
    """
    # Guard against invalid n
    if not isinstance(n, int) or n < 0:
        return []
    # Normalise edges to a list of tuples for safe iteration
    try:
        edge_list = list(edges)
    except TypeError:
        edge_list = []
    # Build adjacency list and indegree counts
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for e in edge_list:
        try:
            a, b = e
        except Exception:
            continue  # skip malformed edge
        if 0 <= a < n and 0 <= b < n:
            adj[a].append(b)
            indeg[b] += 1
    # Use a min‑heap to always pick the smallest available node
    import heapq
    heap = [i for i in range(n) if indeg[i] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heapq.heappush(heap, v)
    # If we couldn't include all nodes, there is a cycle
    if len(order) != n:
        return []
    return order

