    Accepts any iterable of meeting pairs (list, tuple, generator, etc.).
    Ignores malformed entries and meetings where start > end.
    A meeting may start exactly when another ends.
    """
    # Handle falsy or None input
    if not meetings:
        return 0
    # Convert to list for multiple passes and to tolerate generators
    try:
        meetings_list = list(meetings)
    except TypeError:
        return 0
    clean = []
    for m in meetings_list:
        try:
            s, e = m
            # Ensure comparable and proper order
            if isinstance(s, (int, float)) and isinstance(e, (int, float)) and s <= e:
                clean.append((s, e))
        except Exception:
            continue
    if not clean:
        return 0
    # Sort by end time, then start time
    clean.sort(key=lambda x: (x[1], x[0]))
