def solve(a, x):
    """Return leftmost insertion index for x in sorted sequence a.
    Handles any iterable (list, tuple, generator) by converting to list.
    If a is not iterable, treats it as empty.
    """
    try:
        arr = list(a)
    except TypeError:
        arr = []
    # binary search for leftmost insertion point
    lo, hi = 0, len(arr)
    while lo < hi:
        mid = (lo + hi) // 2
        if arr[mid] < x:
            lo = mid + 1
        else:
            hi = mid
    return lo

