import heapq

def solve(n, edges):
    if edges is None:
        edges = []
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for e in edges:
        try:
            a, b = e[0], e[1]
        except Exception:
            continue
        a = int(a); b = int(b)
        if not (0 <= a < n and 0 <= b < n):
            continue
        adj[a].append(b)
        indeg[b] += 1
    heap = [v for v in range(n) if indeg[v] == 0]
    heapq.heapify(heap)
    order = []
    while heap:
        v = heapq.heappop(heap)
        order.append(v)
        for w in adj[v]:
            indeg[w] -= 1
            if indeg[w] == 0:
                heapq.heappush(heap, w)
    if len(order) != n:
        return []
    return order

def solve(nums):
    """Return the length of the longest strictly increasing subsequence.
    Uses O(n log n) patience sorting algorithm.
    Handles empty input.
    """
    import bisect
    tails = []
    for x in nums:
        # Find location to replace in tails
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

