    for r in norm:
        visited.append([False] * len(r))
    def is_land(i, j):
        try:
            val = norm[i][j]
            return int(val) == 1
        except Exception:
            # treat any non‑convertible value as water
            return False
    def bfs(i, j):
        stack = [(i, j)]
        visited[i][j] = True
        while stack:
            ci, cj = stack.pop()
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ni, nj = ci + di, cj + dj
                if 0 <= ni < len(norm) and 0 <= nj < len(norm[ni]):
                    if not visited[ni][nj] and is_land(ni, nj):
                        visited[ni][nj] = True
                        stack.append((ni, nj))
    count = 0
    for i in range(len(norm)):
        for j in range(len(norm[i])):
            if not visited[i][j] and is_land(i, j):
                bfs(i, j)
                count += 1
    return count

